// launch-factory: 상품표와 배송비 — 제품마다 고치는 값이다. 이 파일은 제품 것이다(레지스트리를 다시 받으면 덮어쓸지 묻는다).
// 가격의 정본은 여기다. 브라우저가 보낸 금액·가격은 어디서도 읽지 않는다(장바구니는 상품 id 와 수량만 받는다).
//   id      영문 소문자·숫자·하이픈 1~64자. 주문 기록에 남으므로 한 번 쓴 id 는 바꾸지 않는다
//   price   원화 정수(원). 부가세 포함가로 적는다
//   stock   재고. 적지 않으면 재고 제한이 없다(서비스·무제한 상품). 적으면 처음 쓸 때 이 수로 재고 표에 넣고, 이후는 DB 의 수가 정본이다 — 재고를 고치려면 관리 화면의 「재고」 구획
//   imageUrl  선택. https 또는 사이트 안 경로
// 아래는 예시다 — 가상의 상품이고 실제 상품이 아니다. 지우고 제품의 것을 적는다.
import type { CatalogEntry, ShippingRule } from "@launch-factory/commerce"

export const PRODUCTS: readonly CatalogEntry[] = [
  { id: "example-mug", name: "머그컵(예시)", price: 12000, stock: 20 },
  { id: "example-tote", name: "에코백(예시)", price: 8000 },
  { id: "example-notebook", name: "노트(예시)", price: 4500, stock: 50 },
]

/** 배송비: 기본 3,000원, 5만 원 이상이면 무료. freeOver 를 null 로 두면 늘 fee 를 받고, fee 를 0 으로 두면 늘 무료다 */
export const SHIPPING: ShippingRule = { fee: 3000, freeOver: 50000 }

/** 「내 주문」 화면 경로 — 주문 확인 메일의 버튼이 이 주소(앱 주소 + 경로)로 간다 */
export const ORDERS_PATH = "/orders"

// launch-factory: 상점 조립. 결제 중개(payments)·DB·메일·상품표(catalog)를 @launch-factory/commerce 의 주입 면 하나로 묶는다.
// 상점을 켜는가는 결제가 정한다 — live 에서 PortOne 값이 빠지면 commerceEnabled() 가 false 이고 사이트는 켜진 채 상점 액션만 provider_unavailable(retryable false)로 끝난다.
// 로그인한 사람이 필요한 것(포트)과 사람이 필요 없는 것(웹훅·Cron)이 같은 주입 면을 쓴다.
import { commercePort, defineCatalog, defineShipping, readCatalog, unavailablePort, type CommerceDeps } from "@launch-factory/commerce"
import type { CatalogItem, CommercePort } from "@launch-factory/contract"
import { appUrl, DEFAULT_LOCALE, PRODUCT_NAME } from "@/lib/launch/config"
import { ORDERS_PATH, PRODUCTS, SHIPPING } from "@/lib/launch/catalog"
import { database } from "@/lib/launch/db"
import { mailer } from "@/lib/launch/mailer"
import { payments } from "@/lib/launch/payments"

/** 상점을 여는가. 네트워크·DB 에 닿지 않는다 — 쪽이 상점 대신 안내를 그리고 배포 확인이 경고를 낼 때 읽는다 */
export const commerceEnabled = (): boolean => payments().enabled

let cached: Promise<CommerceDeps> | undefined

/** 상점이 켜져 있을 때의 주입 면(DB·결제·메일·상품표). 꺼져 있으면 던진다 — 부르기 전에 commerceEnabled() 를 본다 */
export function commerceDeps(): Promise<CommerceDeps> {
  return (cached ??= build())
}

async function build(): Promise<CommerceDeps> {
  const config = payments()
  if (!config.enabled) throw new Error(config.reason)
  return {
    db: await database(),
    gateway: config.gateway,
    mailer: mailer(),
    catalog: defineCatalog(PRODUCTS),
    shipping: defineShipping(SHIPPING),
    productName: PRODUCT_NAME,
    ordersUrl: `${appUrl()}${ORDERS_PATH}`,
    locale: DEFAULT_LOCALE,
    // 판매를 막지는 않지만 운영자가 알아야 하는 일(메일 실패·환불 실패). 메시지에는 키·개인정보가 없다
    onError: (e) => console.error(`[commerce] ${e.message}`),
  }
}

/** 로그인한 사람의 판매 포트. 상점이 꺼져 있으면 모든 메서드가 provider_unavailable(retryable false)인 포트를 돌려준다 */
export async function commerceFor(userId: string): Promise<CommercePort> {
  return commerceEnabled() ? commercePort({ ...(await commerceDeps()), userId }) : unavailablePort(DEFAULT_LOCALE)
}

/**
 * 공개 상품 목록(/products)이 읽는 상품표 + 남은 재고. 로그인한 사람이 필요 없다 — 서버 액션이 아니라 서버 컴포넌트가 직접 부른다(브라우저가 부를 수 있는 입구를 더하지 않는다).
 * 상점이 꺼져 있으면 던진다(부르기 전에 commerceEnabled() 를 본다). DB 오류는 그대로 던진다 — 쪽이 오류 상태로 바꾼다.
 */
export async function publicCatalog(): Promise<CatalogItem[]> {
  return readCatalog(await commerceDeps())
}

/** 웹훅 서명 비밀. live 이고 켜져 있을 때만 있다(mock 은 웹훅이 없다) */
export function webhookSecret(): string | undefined {
  const config = payments()
  return config.enabled && config.mode === "live" ? config.webhookSecret : undefined
}

// launch-factory: 상점이 세션을 읽는 한 곳(제품 것 — 첫 설치 때만 놓이고 이후는 제품이 고친다). 기본은 Better Auth 세션이다.
// 상점 서버 액션(app/actions/commerce.ts)은 이 함수 하나로 「누구의 장바구니·주문인가」를 정한다 — userId 는 여기서만 나오고 입력으로는 받지 않는다.
// 로그인 방식을 따로 쓰는 제품(예: 키 없이 켜는 목 인증)은 이 파일만 바꿔 같은 모양 { userId, impersonatedBy } 를 돌려주면 된다.
import { authPort } from "@/lib/launch/auth"

export interface ShopSession {
  userId: string
  /** 관리자가 대신 들어온 세션이면 그 관리자 id — 읽기만 된다 */
  impersonatedBy?: string | null
}

/** 지금 로그인한 사람. 로그아웃·만료·읽기 실패는 null */
export async function shopSession(): Promise<ShopSession | null> {
  const s = await (await authPort()).session()
  return s.ok && s.data ? { userId: s.data.userId, impersonatedBy: s.data.impersonatedBy } : null
}

// launch-factory: 상점이 모르는 결제 번호가 웹훅으로 오면 마지막으로 물어보는 자리. 기본은 「내 것 아님」.
// 같은 결제 중개를 쓰는 다른 기능(예약금 — feature-booking-deposit)이 이 파일을 대신해 자기 결제인지 확인하고 확정한다.
export type PaymentClaim = "confirmed" | "already_confirmed" | "pending" | "not_applicable" | "not_mine"

// 기본형은 결제 번호를 보지 않는다 — 같은 서명으로 이 파일을 대신하는 예약금 항목이 쓴다
// eslint-disable-next-line @typescript-eslint/no-unused-vars
export async function claimOtherPayment(_paymentId: string): Promise<PaymentClaim> {
  return "not_mine"
}

"use server"
// launch-factory: 상점 서버 액션 — 계약 CommercePort 의 메서드와 이름이 같다(catalog · cart · setCartLine · placeOrder · confirmPayment · orders · order · cancelOrder) + 모의 결제 payWithMock.
// 규칙(모든 액션 같다):
//   1. 로그인한 사람의 것만 다룬다. userId 는 세션에서 읽는다 — 입력으로 받지 않는다. 로그아웃이면 code sign_in_required.
//   2. 상점이 꺼져 있으면(live 에서 PortOne 값이 빠짐) code provider_unavailable · retryable false. 사이트는 켜져 있다.
//   3. 쓰는 액션은 요청 제한(guardAction, 사용자·IP 별)을 먼저 지난다. 한도 밖은 code rate_limited·retryAfter 로 막히고 상점 포트에 닿지 않는다.
//   4. 대리 로그인(관리자가 사용자 대신 들어온 세션) 중에는 읽기(catalog · cart · orders · order)만 된다. 나머지는 상점 포트를 부르기 전에 403 으로 막는다.
//   5. 주문하기(placeOrder)와 주문 취소(cancelOrder)는 사람의 확인 입력(`confirmed: true`) 없이는 아무것도 바꾸지 않는다 — code confirmation_required(승인 대기, 오류 아님).
import { blockWhileImpersonating } from "@launch-factory/auth"
import { ownedOrder } from "@launch-factory/commerce"
import type { CommercePort } from "@launch-factory/contract"
import { t } from "@launch-factory/i18n"
import { signInRequiredResult } from "@launch-factory/security/action"
import { headers } from "next/headers"
import { commerceEnabled, commerceFor } from "@/lib/launch/commerce"
import { DEFAULT_LOCALE } from "@/lib/launch/config"
// 세션 읽기는 한 곳(commerce-session.ts)이다 — 이름을 session 으로 받아 서버 액션 인증 검사(ci/server-action-guards.mjs)가 가드로 읽는다
import { shopSession as session, type ShopSession } from "@/lib/launch/commerce-session"
import { database } from "@/lib/launch/db"
import { payments } from "@/lib/launch/payments"
import { guardAction } from "@/lib/launch/security"

const locale = DEFAULT_LOCALE
/** 대리 로그인 중에도 되는 메서드(읽기뿐) */
const COMMERCE_READS = ["catalog", "cart", "orders", "order"] as const
/** 요청 제한 경로(RATE_LIMIT_DEFAULTS) — 읽기는 제한하지 않는다 */
type WriteRoute = "shopCart" | "shopOrder" | "shopConfirm" | "shopCancel"

const providerUnavailable = () => ({ ok: false as const, code: "provider_unavailable", retryable: false, formError: t(locale, "commerce.unavailable") })

/** 세션 → 상점 켜짐 → (쓰기면) 요청 제한 → 대리 로그인 차단 포트. 순서가 바깥에서 안쪽이다 */
async function withPort<R>(route: WriteRoute | null, use: (port: CommercePort, who: ShopSession) => Promise<R>) {
  const s = await session()
  if (!s) return signInRequiredResult(locale)
  if (!commerceEnabled()) return providerUnavailable()
  if (route) {
    const refused = await guardAction(route, { headers: new Headers(await headers()), userId: s.userId })
    if (refused) return refused
  }
  return use(blockWhileImpersonating(await commerceFor(s.userId), s, COMMERCE_READS, locale), s)
}

/** 판매 상품과 지금 살 수 있는 재고 */
export async function catalog() {
  return withPort(null, (port) => port.catalog())
}

/** 내 장바구니(가격은 서버의 상품표 기준) */
export async function cart() {
  return withPort(null, (port) => port.cart())
}

/** 입력: { productId, quantity } — 수량 0 이면 줄을 뺀다 */
export async function setCartLine(input: Parameters<CommercePort["setCartLine"]>[0]) {
  return withPort("shopCart", (port) => port.setCartLine(input))
}

/** 입력: { address, confirmed: true }. 성공하면 결제 대기 주문과 결제창 값(PaymentSession)을 돌려준다 */
export async function placeOrder(input: Parameters<CommercePort["placeOrder"]>[0]) {
  return withPort("shopOrder", (port) => port.placeOrder(input))
}

/** 입력: { orderId, paymentId } — 결제창을 닫은 뒤(리디렉션 반환). 서버가 결제 공급자에 다시 물어 확정한다(웹훅과 같은 경로) */
export async function confirmPayment(input: Parameters<CommercePort["confirmPayment"]>[0]) {
  return withPort("shopConfirm", (port) => port.confirmPayment(input))
}

export async function orders() {
  return withPort(null, (port) => port.orders())
}

/** 입력: { orderId } — 내 주문만 보인다(남의 주문 id 는 not_found) */
export async function order(input: Parameters<CommercePort["order"]>[0]) {
  return withPort(null, (port) => port.order(input))
}

/** 입력: { orderId, reason?, confirmed: true } — 결제 전이면 취소, 결제 후면 환불까지 성공해야 취소된다 */
export async function cancelOrder(input: Parameters<CommercePort["cancelOrder"]>[0]) {
  return withPort("shopCancel", (port) => port.cancelOrder(input))
}

/**
 * 모의 결제(LF_MODE=mock 미리보기 전용): 내 결제 대기 주문의 모의 결제를 「완료」로 만들고 같은 확정 경로(confirmPayment)로 마무리한다.
 * live 에서는 code provider_unsupported 로 거절한다 — 실결제는 PortOne 결제창과 웹훅뿐이다. 입력: { orderId }
 */
export async function payWithMock(input: { orderId: string }) {
  return withPort("shopConfirm", async (port, who) => {
    const pay = async () => {
      const config = payments()
      if (!config.enabled || config.mode !== "mock") return { ok: false as const, code: "provider_unsupported", retryable: false, formError: t(locale, "commerce.unavailable") }
      const orderId = typeof input?.orderId === "string" ? input.orderId : ""
      const mine = await ownedOrder(await database(), orderId, who.userId)
      const notFound = { ok: false as const, code: "not_found", retryable: false, formError: t(locale, "commerce.failure.not_found") }
      if (!mine?.paymentId) return notFound
      try {
        config.gateway.markPaid(mine.paymentId)
      } catch {
        // 서버가 다시 떠서 모의 결제 대기가 사라졌다 — 주문은 만료 Cron 이 정리한다
        return notFound
      }
      return port.confirmPayment({ orderId, paymentId: mine.paymentId })
    }
    // 대리 로그인 중에는 모의 결제도 일으키지 않는다(결제 확정 전에 막는다)
    return blockWhileImpersonating({ pay }, who, [], locale).pay()
  })
}

// launch-factory: 관리 화면 구획 「주문」(계획 3d). 판매 규칙(@launch-factory/commerce)의 서비스를 직접 부른다 — 서버 액션을 감싸지 않는다(입구는 콘솔 하나).
// 접근 벽(관리자 · 2단계 인증 · 대리 세션 · 정지)·확인 입력 벽(주문 취소)·요청 제한·기록은 콘솔이 한다. 이 파일은 무엇을 보이고 어떤 행동이 있는지만 선언한다.
//   목록: 주문 번호(앞 8자)·상태·합계·주문 시각·받는 분(연락처 열이라 콘솔이 가린다). 상세: 줄·합계·받는 분·배송지·송장·상태 요약(상세는 배송에 쓰는 전체 값 — 읽은 기록은 접속 기록에 남는다).
//   행동은 도착 상태 이름이다: mark-preparing(결제 완료 → 준비 중) · mark-shipped(준비 중 → 배송 중, 저장해 둔 송장 번호가 같이 간다) · mark-delivered(배송 중 → 완료). 전이는 판매 규칙의 전이 표가 정한다.
//   cancel 이 유일한 위험 행동이다: 결제된 주문은 전액 환불이 성공해야 취소된다(환불이 안 되면 상태는 그대로). 송장 번호는 폼 저장(행동 단추는 입력을 못 싣는다) — 배송 전 상태에서만 고친다.
//   검색어는 받지 않는다(주문 번호는 길고 받는 분은 가려져 있다) — 상태 거르기로 좁힌다.
import { defineSection, refuse, type AdminCell } from "@launch-factory/admin-console"
import { advanceOrder, cancelOrder, countOrders, listAllOrders, loadOrder, setTrackingNumber, TRACKING_EDITABLE, withDefaults, type Failure, type OrderRecord } from "@launch-factory/commerce"
import type { OrderStatus } from "@launch-factory/contract"
import { commerceDeps, commerceEnabled } from "@/lib/launch/commerce"

const STATUSES = ["pending_payment", "paid", "preparing", "shipped", "delivered", "canceled", "refunded"] as const satisfies readonly OrderStatus[]
const CANCELABLE: readonly OrderStatus[] = ["pending_payment", "paid", "preparing"]

const ctx = async () => withDefaults(await commerceDeps())
const isStatus = (v: string | undefined): v is OrderStatus => STATUSES.includes(v as OrderStatus)
const short = (id: string): string => id.slice(0, 8)
const won = (n: number): string => new Intl.NumberFormat("en-US", { style: "currency", currency: "KRW", maximumFractionDigits: 0 }).format(n)
const when = (d: Date | null): string => (d ? d.toISOString() : "")

/** 판매 규칙의 실패 → 콘솔 거절. 사람 글이 필요한 것만 문구를 싣고(DB·결제 공급자 글은 없다) 나머지는 콘솔의 기본 문구를 쓴다 */
function refusalOf(f: Failure) {
  switch (f.code) {
    case "not_found":
      return refuse("not_found")
    case "invalid_transition":
    case "not_cancelable":
      return refuse("invalid_state")
    case "invalid_input":
      return refuse("invalid_input")
    case "refund_failed":
      return refuse("refund_failed", { formError: "The refund didn't go through, so the order was not canceled. Check the payment provider, then try again." })
    default:
      return refuse("action_failed")
  }
}

/** 한 칸 앞으로 */
const forward = (to: "preparing" | "shipped" | "delivered") => async (_actor: unknown, rec: OrderRecord) => {
  const result = await advanceOrder(await ctx(), { orderId: rec.id, to, ...(to === "shipped" && rec.trackingNumber ? { trackingNumber: rec.trackingNumber } : {}) })
  return result.ok ? undefined : refusalOf(result)
}

export default defineSection({
  id: "orders",
  part: "commerce",
  label: "Orders",
  audience: "admin",
  available: commerceEnabled,
  statuses: STATUSES,
  columns: [
    { id: "id", label: "Order", kind: "text", primary: true },
    { id: "status", label: "Status", kind: "status", filter: true },
    { id: "total", label: "Total", kind: "numeric" },
    { id: "created", label: "Ordered", kind: "date", secondary: true },
    { id: "recipient", label: "Recipient", kind: "contact", secondary: true },
  ],
  list: async (_actor, q) => {
    const status = isStatus(q.status) ? q.status : undefined
    const x = await ctx()
    const [items, total] = await Promise.all([listAllOrders(x.db, { ...(status ? { status } : {}), limit: q.limit, offset: q.offset }), countOrders(x.db, status)])
    return { items, total }
  },
  key: (o) => o.id,
  cells: (o): Record<"id" | "status" | "total" | "created" | "recipient", AdminCell> => ({ id: short(o.id), status: o.status, total: o.total, created: o.createdAt.toISOString(), recipient: o.address?.recipient ?? null }),
  load: async (_actor, id) => loadOrder((await ctx()).db, id),
  view: (o) => ({
    title: `Order ${short(o.id)}`,
    summary: [
      { label: "Status", value: o.status, kind: "status" },
      ...o.items.map((i) => ({ label: i.name, value: `${i.quantity} × ${won(i.unitAmount)}`, kind: "numeric" as const })),
      { label: "Subtotal", value: won(o.subtotal), kind: "numeric" },
      { label: "Shipping", value: won(o.shipping), kind: "numeric" },
      { label: "Total", value: won(o.total), kind: "numeric" },
      { label: "Ordered", value: when(o.createdAt) },
      ...(o.paidAt ? [{ label: "Paid", value: when(o.paidAt) }] : []),
      ...(o.canceledAt ? [{ label: "Canceled", value: when(o.canceledAt) }] : []),
      { label: "Tracking number", value: o.trackingNumber ?? "" },
      ...(o.address
        ? [
            { label: "Recipient", value: o.address.recipient },
            { label: "Phone", value: o.address.phone },
            { label: "Address", value: [o.address.postcode, o.address.address1, o.address.address2].filter(Boolean).join(" ") },
            ...(o.address.note ? [{ label: "Delivery note", value: o.address.note }] : []),
          ]
        : []),
    ],
  }),
  form: {
