  // 상점이 꺼진 사이트(PortOne 값 없음)는 정리할 주문이 없다 — 오류가 아니다
  if (!commerceEnabled()) return Response.json({ skipped: "commerce_disabled" })
  return Response.json(await expirePending(withDefaults(await commerceDeps())))
